// CRM MODULE & PARTNER MANAGEMENT
// ==========================================================================
let selectedCrmPartnerId = null;
let activeCrmRoleFilter = "all";

function updateCrmBadges() {
    const allCount = state.partners.length;
    const customerCount = state.partners.filter(p => p.role === "CUSTOMER" || p.role === "BOTH").length;
    const supplierCount = state.partners.filter(p => p.role === "SUPPLIER" || p.role === "BOTH").length;
    const subcontractorCount = state.partners.filter(p => p.role === "SUBCONTRACTOR").length;

    const badgeAll = document.getElementById("crmBadgeAll");
    const badgeCustomer = document.getElementById("crmBadgeCustomer");
    const badgeSupplier = document.getElementById("crmBadgeSupplier");
    const badgeSubcontractor = document.getElementById("crmBadgeSubcontractor");

    if (badgeAll) badgeAll.textContent = allCount;
    if (badgeCustomer) badgeCustomer.textContent = customerCount;
    if (badgeSupplier) badgeSupplier.textContent = supplierCount;
    if (badgeSubcontractor) badgeSubcontractor.textContent = subcontractorCount;
}

function renderCRM() {
    updateCrmBadges();

    // Populate filter dropdown options if not yet populated
    const regionSelect = document.getElementById("crmRegionFilterSelect");
    const staffSelect = document.getElementById("crmSalesStaffFilterSelect");
    const channelSelect = document.getElementById("crmChannelFilterSelect");

    if (regionSelect && regionSelect.options.length <= 1) {
        const regions = set = new Set();
        state.partners.forEach(p => { if (p.region) regions.add(p.region); });
        Array.from(regions).sort().forEach(r => {
            regionSelect.innerHTML += `<option value="${r}">${r}</option>`;
        });
    }

    if (staffSelect && staffSelect.options.length <= 1) {
        const staffs = new Set();
        state.partners.forEach(p => { if (p.sales_staff) staffs.add(p.sales_staff); });
        Array.from(staffs).sort().forEach(s => {
            staffSelect.innerHTML += `<option value="${s}">${s}</option>`;
        });
    }

    if (channelSelect && channelSelect.options.length <= 1) {
        const channels = new Set();
        state.partners.forEach(p => { if (p.sales_channel) channels.add(p.sales_channel); });
        Array.from(channels).sort().forEach(c => {
            channelSelect.innerHTML += `<option value="${c}">${c}</option>`;
        });
    }

    const query = (document.getElementById("crmSearchInput") ? document.getElementById("crmSearchInput").value : "").toLowerCase().trim();
    const roleFilter = typeof activeCrmRoleFilter !== 'undefined' ? activeCrmRoleFilter : "all";
    const regFilter = regionSelect ? regionSelect.value : "";
    const staffFilter = staffSelect ? staffSelect.value : "";
    const channelFilter = channelSelect ? channelSelect.value : "";
    const custTypeSelect = document.getElementById("crmCustomerTypeFilterSelect");
    const custTypeFilter = custTypeSelect ? custTypeSelect.value : "";

    const filteredPartners = state.partners.filter(p => {
        const q = query;
        const matchesQuery = !q || (p.name || '').toLowerCase().includes(q) ||
                                   (p.code || '').toLowerCase().includes(q) ||
                                   (p.phone || '').includes(q) ||
                                   (p.address || '').toLowerCase().includes(q) ||
                                   (p.region || '').toLowerCase().includes(q) ||
                                   (p.ward || '').toLowerCase().includes(q) ||
                                   (p.sales_staff || '').toLowerCase().includes(q) ||
                                   (p.sales_channel || '').toLowerCase().includes(q) ||
                                   (p.note || '').toLowerCase().includes(q);

        const matchesRole = roleFilter === "all" || p.role === roleFilter || (p.role === "BOTH" && (roleFilter === "CUSTOMER" || roleFilter === "SUPPLIER"));
        const matchesRegion = !regFilter || p.region === regFilter;
        const matchesStaff = !staffFilter || p.sales_staff === staffFilter;
        const matchesChannel = !channelFilter || p.sales_channel === channelFilter;
        
        const isCustWholesale = (p.customer_type === "WHOLESALE" || p.customer_type === "Khách sỉ" || p.customer_type === "SI");
        const matchesCustType = !custTypeFilter || 
            (custTypeFilter === "WHOLESALE" && isCustWholesale) ||
            (custTypeFilter === "RETAIL" && !isCustWholesale);

        return matchesQuery && matchesRole && matchesRegion && matchesStaff && matchesChannel && matchesCustType;
    });

    const tableBody = document.querySelector("#crmTable tbody");
    if (!tableBody) return;
    tableBody.innerHTML = "";

    if (filteredPartners.length === 0) {
        tableBody.innerHTML = `<tr><td colspan="14" class="text-muted text-center" style="padding: 24px;">Không tìm thấy khách hàng / đối tác nào</td></tr>`;
        return;
    }

    filteredPartners.forEach(p => {
        const roleLabels = { CUSTOMER: "Khách hàng", SUPPLIER: "Nhà cung cấp", SUBCONTRACTOR: "Đơn vị gia công", BOTH: "Khách & NCC" };
        
        let spendVal = 0;
        let debtVal = 0;

        if (p.role === "CUSTOMER" || p.role === "BOTH") {
            const stdSpend = (state.orders || []).filter(o => o.customer_id === p.id).reduce((sum, o) => sum + (o.total_amount || 0), 0);
            const onlineSpend = (state.online_orders || []).filter(o => o.customer_id === p.id || o.customer_code === p.code).reduce((sum, o) => sum + (o.total_amount || 0), 0);
            spendVal = stdSpend + onlineSpend;
            const paid = (state.transactions || []).filter(t => (t.partner_id === p.id || t.customer_code === p.code) && t.type === "RECEIPT").reduce((sum, t) => sum + (t.amount || 0), 0);
            const onlinePaid = (state.online_orders || []).filter(o => (o.customer_id === p.id || o.customer_code === p.code)).reduce((sum, o) => sum + (o.paid_amount || 0), 0);
            const actualTotalPaid = Math.max(paid, onlinePaid);
            debtVal = Math.max(0, spendVal - actualTotalPaid);
        } else if (p.role === "SUBCONTRACTOR") {
            spendVal = state.subcontracts.filter(s => s.subcontractor_id === p.id).reduce((sum, s) => sum + s.cost, 0);
            const paid = state.transactions.filter(t => t.partner_id === p.id && t.type === "PAYMENT" && t.category === "SUBCONTRACTOR_PAY").reduce((sum, t) => sum + t.amount, 0);
            debtVal = Math.max(0, spendVal - paid);
        } else if (p.role === "SUPPLIER") {
            spendVal = state.restocks.filter(r => r.supplier_id === p.id).reduce((sum, r) => sum + r.total_amount, 0);
            const paid = state.transactions.filter(t => t.partner_id === p.id && t.type === "PAYMENT" && t.category === "SUPPLIER_PAY").reduce((sum, t) => sum + t.amount, 0);
            debtVal = Math.max(0, spendVal - paid);
        }

        const statusBadge = p.status !== false ? `<span class="badge badge-success">Đang làm việc</span>` : `<span class="badge badge-danger">Tạm dừng</span>`;

        const isWholesale = (p.customer_type === "WHOLESALE" || p.customer_type === "Khách sỉ" || p.customer_type === "SI");
        const custTypeBadge = isWholesale 
            ? `<span class="badge badge-warning" style="font-size:0.75rem; background:#fef3c7; color:#b45309; border:1px solid #fde68a;">🏢 Khách sỉ</span>`
            : `<span class="badge badge-info" style="font-size:0.75rem; background:#e0f2fe; color:#0369a1; border:1px solid #bae6fd;">👤 Khách lẻ</span>`;

        const row = document.createElement("tr");
        row.innerHTML = `
            <td><a href="javascript:void(0)" onclick="window.openEditPartner('${p.id}')" style="text-decoration:underline; font-weight:700; color:var(--accent);"><strong>${p.code || 'N/A'}</strong></a></td>
            <td>
                <strong>${p.name || ''}</strong>
                ${p.company_name && p.company_name !== p.name ? `<div style="font-size:0.75rem; color:var(--text-muted); margin-top:2px;" title="Tên công ty"><i data-lucide="building" style="width:11px; height:11px; display:inline-block; vertical-align:middle;"></i> ${p.company_name}</div>` : ''}
                ${p.contact_person && p.contact_person !== p.name && p.contact_person !== 'Đại diện công ty' ? `<div style="font-size:0.75rem; color:var(--accent); margin-top:1px;" title="Người liên hệ"><i data-lucide="user" style="width:11px; height:11px; display:inline-block; vertical-align:middle;"></i> ${p.contact_person}</div>` : ''}
            </td>
            <td>${custTypeBadge}</td>
            <td>${p.phone || 'N/A'}</td>
            <td>${p.address || '<span class="text-muted">-</span>'}</td>
            <td>${p.region ? `<span class="badge badge-info" style="font-size:0.75rem;">${p.region}</span>` : '<span class="text-muted">-</span>'}</td>
            <td>${p.ward || '<span class="text-muted">-</span>'}</td>
            <td>${p.sales_staff ? `<span class="badge badge-primary" style="font-size:0.75rem; font-weight:600;">${p.sales_staff}</span>` : '<span class="text-muted">-</span>'}</td>
            <td>${p.sales_channel ? `<span class="badge badge-secondary" style="font-size:0.75rem;">${p.sales_channel}</span>` : '<span class="text-muted">-</span>'}</td>
            <td style="max-width:180px; overflow:hidden; text-overflow:ellipsis; white-space:nowrap;" title="${p.note || ''}">${p.note || '<span class="text-muted">-</span>'}</td>
            <td><strong>${typeof formatMoney === 'function' ? formatMoney(spendVal) : spendVal}</strong></td>
            <td class="${debtVal > 0 ? 'text-warning font-bold' : ''}">${typeof formatMoney === 'function' ? formatMoney(debtVal) : debtVal}</td>
            <td>${statusBadge}</td>
            <td>
                <div class="card-actions-row">
                    <button class="btn btn-secondary" style="padding: 4px 8px; font-size: 0.75rem;" onclick="window.openCrmDetail('${p.id}')">Xem CRM</button>
                    <button class="btn-icon" onclick="window.viewPartnerBillingDetails('${p.id}')" title="Xem Hóa đơn VAT / Trụ sở"><i data-lucide="receipt"></i></button>
                    <button class="btn-icon" onclick="window.openEditPartner('${p.id}')" title="Sửa"><i data-lucide="edit-2"></i></button>
                    <button class="btn-icon" style="color:var(--danger)" onclick="window.deletePartner('${p.id}')" title="Xóa"><i data-lucide="trash-2"></i></button>
                </div>
            </td>
        `;
        tableBody.appendChild(row);
    });
    if (typeof lucide !== 'undefined' && lucide.createIcons) lucide.createIcons();
}


